insert into public.packs (id, title, title_de, description, description_de, unlock_rule, unlock_text, unlock_text_de) values ('renaissance', 'Renaissance Masters', 'Meister der Renaissance', '25 works from van Eyck to El Greco, painted when perspective was the latest thing.', '25 Werke von van Eyck bis El Greco, aus der Zeit, als die Perspektive der letzte Schrei war.', '{"type": "solo_games", "n": 5}', 'Play 5 solo games to unlock.', 'Spiel 5 Solo-Partien, um das Pack freizuschalten.') on conflict (id) do nothing;
insert into public.packs (id, title, title_de, description, description_de, unlock_rule, unlock_text, unlock_text_de) values ('impressionists', 'Impressionists', 'Impressionisten', '25 works from Monet to van Gogh, painted when artists took their easels outside.', '25 Werke von Monet bis van Gogh, aus der Zeit, als die Maler mit der Staffelei ins Freie zogen.', '{"type": "dailies_played", "n": 5}', 'Play 5 daily challenges to unlock.', 'Spiel 5 Tageschallenges, um das Pack freizuschalten.') on conflict (id) do nothing;
insert into public.packs (id, title, title_de, description, description_de, unlock_rule, unlock_text, unlock_text_de) values ('german-artists', 'German Artists', 'Deutsche Künstler', '25 works by German-speaking artists, from Dürer to the Blue Rider.', '25 Werke deutschsprachiger Künstler, von Dürer bis zum Blauen Reiter.', '{"type": "daily_streak", "n": 3}', 'Play the daily challenge 3 days in a row to unlock.', 'Spiel die Tageschallenge an 3 Tagen hintereinander, um das Pack freizuschalten.') on conflict (id) do nothing;
insert into public.packs (id, title, title_de, description, description_de, unlock_rule, unlock_text, unlock_text_de) values ('baroque-masters', 'Baroque Masters', 'Meister des Barock', '25 works from Rubens to Vermeer, painted when candlelight was the star.', '25 Werke von Rubens bis Vermeer, aus der Zeit, als Kerzenlicht der Star war.', '{"type": "runs_finished", "n": 3}', 'Finish 3 runs to unlock.', 'Schließ 3 Runs ab, um das Pack freizuschalten.') on conflict (id) do nothing;
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('bbeddjkcth', 'pack:baroque-masters:1604-caravaggio-the-entombment-of-christ', 'The Entombment of Christ', 'Caravaggio', 1604, '1602–1604', 'Baroque', 'oil on canvas', 'Pinacoteca Vaticana, Vatican City', 2, 'object', 'https://nambatu.github.io/circart-preview/art/bbeddjkcth.jpg', 'Painted for a chapel in Rome''s Chiesa Nuova, the original was carried off to Paris by Napoleon''s troops and ended up in the Vatican when it came back; a copy hangs in the chapel today. Caravaggio seems to have given Nicodemus, the man bracing Christ''s legs, the face of Michelangelo.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('nd7g77z9pz', 'pack:baroque-masters:1608-hendrick-avercamp-winter-landscape-with-ice-skaters', 'Winter Landscape with Ice Skaters', 'Hendrick Avercamp', 1608, 'c. 1608', 'Dutch Golden Age', 'oil on oak panel', 'Rijksmuseum, Amsterdam', 2, 'object', 'https://nambatu.github.io/circart-preview/art/nd7g77z9pz.jpg', 'Avercamp, nicknamed ''the Mute of Kampen'' because he could not speak, was the first Dutch painter to specialise in winter scenes. He borrowed a lot from Pieter Bruegel the Elder, right down to the wooden bird trap. Hunt for his signature: it''s scratched like graffiti onto the fishermen''s hut in the foreground.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('epe9arkx9p', 'pack:baroque-masters:1611-peter-paul-rubens-the-elevation-of-the-cross', 'The Elevation of the Cross', 'Peter Paul Rubens', 1611, '1610–1611', 'Baroque', 'oil on panel (triptych)', 'Cathedral of Our Lady, Antwerp', 1, 'object', 'https://nambatu.github.io/circart-preview/art/epe9arkx9p.jpg', 'This huge triptych, painted soon after Rubens came home from Italy, brought full-blown Baroque drama to Flanders and made him the star of Antwerp. German occupiers removed it in the First World War, but it was returned afterwards. The man in armour hauling up the cross may be Rubens himself.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('bswvv9bgwk', 'pack:baroque-masters:1615-clara-peeters-still-life-with-cheeses-almonds-and-pret', 'Still Life with Cheeses, Almonds and Pretzels', 'Clara Peeters', 1615, 'c. 1615', 'Baroque', 'oil on panel', 'Mauritshuis, The Hague', 3, 'object', 'https://nambatu.github.io/circart-preview/art/bswvv9bgwk.jpg', 'Clara Peeters was one of very few women working as professional painters in Flanders, and she liked to hide herself in her pictures: look closely at the lid of the stoneware jug and you''ll find her tiny reflected self-portrait. She also signed her name on the handle of the silver knife.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('mnybdzdkfv', 'pack:baroque-masters:1619-guido-reni-atalanta-and-hippomenes', 'Atalanta and Hippomenes', 'Guido Reni', 1619, '1618–1619', 'Baroque', 'oil on canvas', 'Museo del Prado, Madrid', 3, 'object', 'https://nambatu.github.io/circart-preview/art/mnybdzdkfv.jpg', 'In the myth, the swift huntress Atalanta would only marry a man who could beat her in a race – losers were put to death. Hippomenes won by dropping golden apples from Venus, which she stopped to pick up. Reni painted two almost identical versions; the one in Madrid came first, the other hangs in Naples.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('2gangk5xmz', 'pack:baroque-masters:1622-diego-vel-zquez-the-waterseller-of-seville', 'The Waterseller of Seville', 'Diego Velázquez', 1622, '1618–1622', 'Baroque', 'oil on canvas', 'Apsley House, London', 2, 'object', 'https://nambatu.github.io/circart-preview/art/2gangk5xmz.jpg', 'Velázquez painted this in Seville while still in his late teens or early twenties. Joseph Bonaparte had it in his baggage when he fled Spain; the Duke of Wellington captured it at the Battle of Vitoria, and the grateful Spanish king let him keep it. That''s why it hangs in Wellington''s London home.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('2hu69sbpnz', 'pack:baroque-masters:1625-gerard-van-honthorst-the-matchmaker', 'The Matchmaker', 'Gerard van Honthorst', 1625, null, 'Dutch Golden Age', 'oil on panel', 'Centraal Museum, Utrecht', 3, 'object', 'https://nambatu.github.io/circart-preview/art/2hu69sbpnz.jpg', 'In Rome, Honthorst''s candle-lit scenes in the style of Caravaggio earned him the nickname ''Gherardo delle Notti'' – Gerard of the Nights. Here a young man, a girl with a lute and an old procuress strike a deal; Dutch viewers knew the lute as a symbol of lust.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('rp9jsftwzf', 'pack:baroque-masters:1633-rembrandt-the-storm-on-the-sea-of-galilee', 'The Storm on the Sea of Galilee', 'Rembrandt', 1633, null, 'Dutch Golden Age', 'oil on canvas', 'Stolen from the Isabella Stewart Gardner Museum, Boston (whereabouts unknown)', 1, 'object', 'https://nambatu.github.io/circart-preview/art/rp9jsftwzf.jpg', 'Rembrandt''s only seascape – and nobody has seen it in public for decades. It was stolen in the largest art heist in US history, when thieves posing as police officers walked out of the Gardner Museum with thirteen works. Among the panicking disciples, one man looks straight out at you: Rembrandt himself.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('8r2z3zxnbd', 'pack:baroque-masters:1635-anthony-van-dyck-charles-i-at-the-hunt', 'Charles I at the Hunt', 'Anthony van Dyck', 1635, 'c. 1635', 'Baroque', 'oil on canvas', 'Louvre, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/8r2z3zxnbd.jpg', 'Charles I was self-conscious about being short, so van Dyck painted him from a low viewpoint, effortlessly elegant, looking down at us. The king haggled over the bill: van Dyck asked for £200 and got £100. A Latin inscription boldly calls him King of Great Britain.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('fsc4jg2v2d', 'pack:baroque-masters:1638-rembrandt-belshazzar-s-feast', 'Belshazzar''s Feast', 'Rembrandt', 1638, 'c. 1636–1638', 'Dutch Golden Age', 'oil on canvas', 'National Gallery, London', 1, 'object', 'https://nambatu.github.io/circart-preview/art/fsc4jg2v2d.jpg', 'A hand appears out of nowhere and writes on the wall – the origin of the phrase ''the writing on the wall''. Rembrandt''s friend, the Jewish scholar Menasseh ben Israel, suggested the Hebrew letters were written in columns, top to bottom, which explains why the Babylonian wise men couldn''t read them. Rembrandt''s wife Saskia probably posed for the woman beside the king.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('8sgh69svt7', 'pack:baroque-masters:1642-le-nain-brothers-peasant-family-in-an-interior', 'Peasant Family in an Interior', 'Le Nain brothers', 1642, 'c. 1642', 'Baroque', 'oil on canvas', 'Louvre, Paris', 3, 'object', 'https://nambatu.github.io/circart-preview/art/8sgh69svt7.jpg', 'Three brothers from Laon shared a workshop in Paris and often signed simply ''Le Nain'', so experts still argue over which of them painted what. Unusually for the time, this large canvas shows poor peasants with quiet dignity instead of as figures of fun: three generations gathered by the fire in the evening light.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('kpcutaxrj8', 'pack:baroque-masters:1647-paulus-potter-the-young-bull', 'The Young Bull', 'Paulus Potter', 1647, null, 'Dutch Golden Age', 'oil on canvas', 'Mauritshuis, The Hague', 3, 'object', 'https://nambatu.github.io/circart-preview/art/kpcutaxrj8.jpg', 'Paulus Potter was only about 22 when he painted this life-size bull, and he even sewed on extra strips of canvas to make it bigger. Livestock experts think the animal is a composite of studies of six different bulls. Napoleon''s troops carried it off to Paris; Potter himself died of tuberculosis aged just 28.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4vfk6m65mc', 'pack:baroque-masters:1648-claude-lorrain-seaport-with-the-embarkation-of-the-quee', 'Seaport with the Embarkation of the Queen of Sheba', 'Claude Lorrain', 1648, null, 'Baroque Classicism', 'oil on canvas', 'National Gallery, London', 2, 'object', 'https://nambatu.github.io/circart-preview/art/4vfk6m65mc.jpg', 'Claude was famous for painting light itself: here a low sun glares straight at you across a classical harbour as the Queen of Sheba sets off to visit King Solomon. J. M. W. Turner admired it so much that he left two of his own paintings to the nation on condition they hang beside Claude''s – and they still do.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4zee4anhyn', 'pack:baroque-masters:1651-diego-vel-zquez-rokeby-venus', 'Rokeby Venus', 'Diego Velázquez', 1651, 'c. 1647–1651', 'Baroque', 'oil on canvas', 'National Gallery, London', 1, 'object', 'https://nambatu.github.io/circart-preview/art/4zee4anhyn.jpg', 'Velázquez''s only surviving female nude – a daring subject in Spain, where the Inquisition frowned on such pictures. Her face in the mirror is blurred and far too big to be a real reflection, an illusion now called the ''Venus effect''. A suffragette once slashed the canvas seven times with a meat cleaver.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('fjm76rws6e', 'pack:baroque-masters:1654-carel-fabritius-the-goldfinch', 'The Goldfinch', 'Carel Fabritius', 1654, null, 'Dutch Golden Age', 'oil on panel', 'Mauritshuis, The Hague', 1, 'object', 'https://nambatu.github.io/circart-preview/art/fjm76rws6e.jpg', 'Fabritius, Rembrandt''s most gifted pupil, was killed aged 32 when the Delft gunpowder magazine exploded, destroying his studio and much of his work – the same year he painted this little bird. The panel was meant to trick the eye like a real bird on its perch, then vanished for two centuries. It later gave its name to Donna Tartt''s novel.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('jqd4bsyrt7', 'pack:baroque-masters:1657-diego-vel-zquez-las-hilanderas-the-spinners', 'Las Hilanderas (The Spinners)', 'Diego Velázquez', 1657, 'c. 1657 (some scholars date it 1644–1648)', 'Baroque', 'oil on canvas', 'Museo del Prado, Madrid', 2, 'object', 'https://nambatu.github.io/circart-preview/art/jqd4bsyrt7.jpg', 'It looks like an everyday scene in a royal tapestry workshop, but the background hides the myth of Arachne, the weaver who dared to challenge the goddess Athena. The tapestry at the back copies Titian''s Rape of Europa, Velázquez''s tribute to his great hero. Later owners stitched extra strips onto the canvas, which the Prado now hides behind a screen.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4xzbkjw3qz', 'pack:baroque-masters:1661-johannes-vermeer-view-of-delft', 'View of Delft', 'Johannes Vermeer', 1661, 'c. 1660–1661', 'Dutch Golden Age', 'oil on canvas', 'Mauritshuis, The Hague', 1, 'object', 'https://nambatu.github.io/circart-preview/art/4xzbkjw3qz.jpg', 'Marcel Proust adored this painting and wrote the death of the writer Bergotte in front of it into In Search of Lost Time. Vermeer painted his home town from the south, across the harbour – the part of Delft left undamaged by the great gunpowder explosion a few years earlier.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('c8kwkf7jnr', 'pack:baroque-masters:1662-rembrandt-syndics-of-the-drapers-guild', 'Syndics of the Drapers'' Guild', 'Rembrandt', 1662, null, 'Dutch Golden Age', 'oil on canvas', 'Rijksmuseum, Amsterdam', 2, 'object', 'https://nambatu.github.io/circart-preview/art/c8kwkf7jnr.jpg', 'Five cloth inspectors of Amsterdam''s drapers'' guild look up from their sample book as if you''ve just walked in on their meeting. Rembrandt was in deep financial trouble and living in a rented house, yet still landed this prestigious commission. The picture later became world-famous on the boxes of Dutch Masters cigars.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('y9gqczwtnb', 'pack:baroque-masters:1663-johannes-vermeer-woman-holding-a-balance', 'Woman Holding a Balance', 'Johannes Vermeer', 1663, 'c. 1662–1663', 'Dutch Golden Age', 'oil on canvas', 'National Gallery of Art, Washington, D.C.', 2, 'object', 'https://nambatu.github.io/circart-preview/art/y9gqczwtnb.jpg', 'For a long time it was called ''Woman Weighing Gold'' – until a microscope showed that the scales in her hand are empty. Behind her hangs a painting of the Last Judgement, where souls are weighed, turning a quiet domestic moment into a meditation on balance and judgement.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('thvg94nttn', 'pack:baroque-masters:1669-rembrandt-the-jewish-bride', 'The Jewish Bride', 'Rembrandt', 1669, 'c. 1665–1669', 'Dutch Golden Age', 'oil on canvas', 'Rijksmuseum, Amsterdam', 1, 'object', 'https://nambatu.github.io/circart-preview/art/thvg94nttn.jpg', 'The title was made up by a collector long after Rembrandt''s death, who thought it showed a Jewish father giving his daughter a necklace on her wedding day. Nobody really knows who the couple are – perhaps Isaac and Rebecca from the Bible. Vincent van Gogh said he''d give ten years of his life to sit in front of it for a fortnight with only a crust of bread.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('jub6tvt524', 'pack:baroque-masters:1672-juan-de-vald-s-leal-in-ictu-oculi', 'In Ictu Oculi', 'Juan de Valdés Leal', 1672, '1670–1672', 'Baroque', 'oil on canvas', 'Hospital de la Caridad, Seville', 3, 'object', 'https://nambatu.github.io/circart-preview/art/jub6tvt524.jpg', 'A skeleton snuffs out a candle while standing on crowns, a papal tiara and books: ''in the blink of an eye'', all worldly glory ends. It was painted for a charitable brotherhood in Seville that cared for the old and buried the poor. Its companion piece is even grimmer, showing the rotting corpses of a bishop and a knight.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('2t74xz9r5e', 'pack:baroque-masters:1678-bartolom-esteban-murillo-the-immaculate-conception-of-los-venerab', 'The Immaculate Conception of Los Venerables', 'Bartolomé Esteban Murillo', 1678, 'c. 1678', 'Baroque', 'oil on canvas', 'Museo del Prado, Madrid', 2, 'object', 'https://nambatu.github.io/circart-preview/art/2t74xz9r5e.jpg', 'Murillo painted the Immaculate Conception around two dozen times, and this triumphant version is the most famous. Napoleon''s Marshal Soult looted it during the Peninsular War but left the frame behind in Seville, where it still is. When the Louvre later bought it, it was reportedly the highest price ever paid for a painting.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('xvm2acmf7n', 'pack:baroque-masters:1689-meindert-hobbema-the-avenue-at-middelharnis', 'The Avenue at Middelharnis', 'Meindert Hobbema', 1689, null, 'Dutch Golden Age', 'oil on canvas', 'National Gallery, London', 2, 'object', 'https://nambatu.github.io/circart-preview/art/xvm2acmf7n.jpg', 'Painted long after Hobbema had mostly given up art for a steady job as a wine gauger for the Amsterdam excise, it became his most famous picture. The young trees lining the road had been planted only about twenty-five years earlier, which helped date it. X-rays show he first painted two more trees in the foreground, then painted them out.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4bs4yrhrkb', 'pack:baroque-masters:1701-hyacinthe-rigaud-portrait-of-louis-xiv', 'Portrait of Louis XIV', 'Hyacinthe Rigaud', 1701, null, 'Baroque', 'oil on canvas', 'Louvre, Paris', 1, 'object', 'https://nambatu.github.io/circart-preview/art/4bs4yrhrkb.jpg', 'Louis XIV ordered it as a gift for his grandson, the new King of Spain – but liked it so much that he kept the original and sent a copy instead. The Sun King was in his sixties, yet proudly shows off his legs in silk stockings and red-heeled shoes. Rigaud painted the face on a small separate canvas that was later stitched into the big one.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('8qjxdkw7g7', 'pack:baroque-masters:1716-rachel-ruysch-still-life-with-flowers-on-a-marble-slab', 'Still Life with Flowers on a Marble Slab', 'Rachel Ruysch', 1716, null, 'Dutch Golden Age', 'oil on canvas', 'Rijksmuseum, Amsterdam', 3, 'object', 'https://nambatu.github.io/circart-preview/art/8qjxdkw7g7.jpg', 'Rachel Ruysch was one of the best-paid painters of her day and court painter to the Elector Palatine in Düsseldorf; her pictures could sell for more than a Rembrandt. Her father was a famous anatomist and botanist, which may explain the scientific precision of her flowers and insects – you can spot poppies, pansies and a bottle fly.', 'baroque-masters', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('tgqtnm3rt8', 'pack:german-artists:1502-albrecht-d-rer-young-hare', 'Young Hare', 'Albrecht Dürer', 1502, null, 'Northern Renaissance', 'watercolour and bodycolour on paper', 'Albertina, Vienna', 1, 'object', 'https://nambatu.github.io/circart-preview/art/tgqtnm3rt8.jpg', 'Despite the English title, this is a fully grown hare – the German name is simply ''Feldhase''. Dürer signed and dated it boldly, treating it as a finished artwork rather than a study. The window reflected in its eye is often taken as proof he had a live hare in his studio, though he put that same reflection into lots of eyes.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('yh5x7ztkup', 'pack:german-artists:1508-albrecht-d-rer-praying-hands', 'Praying Hands', 'Albrecht Dürer', 1508, 'c. 1508', 'Northern Renaissance', 'pen and ink with white heightening on blue-prepared paper', 'Albertina, Vienna', 1, 'object', 'https://nambatu.github.io/circart-preview/art/yh5x7ztkup.jpg', 'Long thought to be a study for an apostle in an altarpiece that later burned, these hands became the most reproduced image of prayer in the Western world – on posters, mugs, phone cases and gravestones. Even Andy Warhol''s tombstone carries a version of them.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('3sctenfs83', 'pack:german-artists:1515-albrecht-d-rer-rhinoceros', 'Rhinoceros', 'Albrecht Dürer', 1515, null, 'Northern Renaissance', 'woodcut', 'National Gallery of Art, Washington, D.C. (one of many impressions)', 1, 'object', 'https://nambatu.github.io/circart-preview/art/3sctenfs83.jpg', 'Dürer never saw a rhinoceros: he worked from a sketch and a written description of the first one to reach Europe since Roman times. That''s why his beast seems to wear plate armour and has an extra little horn on its back. The real animal drowned in a shipwreck on its way to the Pope, but Dürer''s version stayed the standard picture of a rhino for centuries.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('3wfmfgyt6a', 'pack:german-artists:1522-hans-holbein-the-younger-the-body-of-the-dead-christ-in-the-tomb', 'The Body of the Dead Christ in the Tomb', 'Hans Holbein the Younger', 1522, '1520–1522', 'Northern Renaissance', 'oil and tempera on limewood', 'Kunstmuseum Basel, Basel', 2, 'object', 'https://nambatu.github.io/circart-preview/art/3wfmfgyt6a.jpg', 'A life-size corpse squeezed into a box only about 30 cm high, showing Christ''s body with the first signs of decay. Fyodor Dostoevsky was so shaken by it that his wife dragged him away, fearing it would trigger an epileptic fit – he later put it into his novel The Idiot.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('pyefbjc24a', 'pack:german-artists:1529-albrecht-altdorfer-the-battle-of-alexander-at-issus', 'The Battle of Alexander at Issus', 'Albrecht Altdorfer', 1529, null, 'Northern Renaissance', 'oil on limewood panel', 'Alte Pinakothek, Munich', 2, 'object', 'https://nambatu.github.io/circart-preview/art/pyefbjc24a.jpg', 'Thousands of tiny soldiers clash beneath a swirling cosmic sky, with the curve of the Earth in the distance. Alexander''s men wear the painter''s own era''s armour and the Persians look like Ottoman Turks – a nod to the Turkish threat at the time. Napoleon carried it off to France, and it reportedly hung in his bathroom at Saint-Cloud.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('vu8zgkbdq9', 'pack:german-artists:1537-hans-holbein-the-younger-portrait-of-henry-viii', 'Portrait of Henry VIII', 'Hans Holbein the Younger', 1537, 'c. 1537 (Wikipedia: c. 1534–1536)', 'Northern Renaissance', 'oil on oak panel', 'Museo Thyssen-Bornemisza, Madrid', 1, 'object', 'https://nambatu.github.io/circart-preview/art/vu8zgkbdq9.jpg', 'This small panel is the only painting of Henry VIII by Holbein''s own hand to survive; the famous full-length image is known only from copies, because the original mural burned with Whitehall Palace. Holbein flattered his king: he looks strong and healthy, though he had recently been badly hurt in a jousting accident.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('25vhpqkph8', 'pack:german-artists:1544-hans-baldung-the-ages-and-death', 'The Ages and Death', 'Hans Baldung', 1544, '1541–1544', 'Northern Renaissance', 'oil on panel', 'Museo del Prado, Madrid', 3, 'object', 'https://nambatu.github.io/circart-preview/art/25vhpqkph8.jpg', 'Death, holding an hourglass, already has the old woman by the arm while she clings to a young beauty – a blunt reminder that youth doesn''t last. A baby sleeps on the ground, and the sky is split between a hellish darkness and a crucified Christ in heavenly light. Baldung trained in Dürer''s workshop and loved macabre subjects like this.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('9wzqsy5nw8', 'pack:german-artists:1546-lucas-cranach-the-elder-the-fountain-of-youth', 'The Fountain of Youth', 'Lucas Cranach the Elder', 1546, null, 'Northern Renaissance', 'oil on lime panel', 'Gemäldegalerie, Berlin', 2, 'object', 'https://nambatu.github.io/circart-preview/art/9wzqsy5nw8.jpg', 'Old women are carried, carted and wheeled into a magic pool on the left and climb out young and beautiful on the right, straight into a party with feasting and dancing. Showing elderly nude women was highly unusual at the time. A statue of Venus and Cupid crowns the fountain, hinting that the real magic is love.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('ks7nvmjc36', 'pack:german-artists:1609-adam-elsheimer-the-flight-into-egypt', 'The Flight into Egypt', 'Adam Elsheimer', 1609, 'c. 1609', 'Baroque', 'oil on copper', 'Alte Pinakothek, Munich', 3, 'object', 'https://nambatu.github.io/circart-preview/art/ks7nvmjc36.jpg', 'Painted on a small copper plate in Rome, this is thought to be the first naturalistic night sky in Western art – with the Milky Way, a full moon reflected in the water and recognisable constellations. The Frankfurt-born Elsheimer died young soon afterwards, but prints spread the image, and Rembrandt is thought to have been inspired by it.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('t96u9r2qpd', 'pack:german-artists:1787-johann-heinrich-wilhelm-tischbein-goethe-in-the-roman-campagna', 'Goethe in the Roman Campagna', 'Johann Heinrich Wilhelm Tischbein', 1787, null, 'Neoclassicism', 'oil on canvas', 'Städel Museum, Frankfurt', 1, 'object', 'https://nambatu.github.io/circart-preview/art/t96u9r2qpd.jpg', 'Goethe travelled through Italy incognito as ''Filippo Miller'', and his friend Tischbein painted him lounging among Roman ruins in a big white travelling cloak. Look at his feet – generations of viewers have joked that Goethe seems to have two left ones. The relief behind him shows a scene from Goethe''s play Iphigenia in Tauris, which he had read aloud to the painter.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('th6n56anfn', 'pack:german-artists:1806-philipp-otto-runge-the-h-lsenbeck-children', 'The Hülsenbeck Children', 'Philipp Otto Runge', 1806, '1805–1806', 'Romanticism', 'oil on canvas', 'Hamburger Kunsthalle, Hamburg', 3, 'object', 'https://nambatu.github.io/circart-preview/art/th6n56anfn.jpg', 'The three children of a Hamburg merchant, aged five, four and two, play in their garden, seen from their own eye level. Painting children as real children rather than stiff little adults was something new in German art. Runge, a key figure of German Romanticism alongside Friedrich, died of tuberculosis at just 33.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('6d9wdqafb9', 'pack:german-artists:1810-caspar-david-friedrich-the-monk-by-the-sea', 'The Monk by the Sea', 'Caspar David Friedrich', 1810, '1808–1810', 'Romanticism', 'oil on canvas', 'Alte Nationalgalerie, Berlin', 1, 'object', 'https://nambatu.github.io/circart-preview/art/6d9wdqafb9.jpg', 'A tiny figure stands before an almost empty sea and sky – so radical that Heinrich von Kleist wrote it had ''no foreground except the frame''. Scans show Friedrich first painted little ships on the horizon, then removed them to make the emptiness total. The Prussian king bought it together with its partner piece, The Abbey in the Oakwood, and they still hang side by side.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('qehnu24gxb', 'pack:german-artists:1839-carl-spitzweg-the-poor-poet', 'The Poor Poet', 'Carl Spitzweg', 1839, null, 'Biedermeier', 'oil on canvas', 'Neue Pinakothek, Munich', 1, 'object', 'https://nambatu.github.io/circart-preview/art/qehnu24gxb.jpg', 'A penniless poet lies in bed in his freezing attic, an umbrella rigged against the leaking roof and a stack of his own manuscripts by the stove. Spitzweg painted three versions: one was stolen from Berlin''s Charlottenburg Palace and has never been found, and another was briefly ''kidnapped'' by the performance artist Ulay as a political action.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('dddeawctgz', 'pack:german-artists:1845-adolph-menzel-the-balcony-room', 'The Balcony Room', 'Adolph Menzel', 1845, null, 'Realism', 'oil on cardboard', 'Alte Nationalgalerie, Berlin', 3, 'object', 'https://nambatu.github.io/circart-preview/art/dddeawctgz.jpg', 'Just a breeze lifting a curtain, sunlight on the floorboards and a half-empty room – the opposite of the cosy, cluttered interiors of the time. Menzel kept this small private study to himself for decades; the museum only acquired it two years before his death. Today it looks almost like Impressionism before Impressionism.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('wbvtadtmax', 'pack:german-artists:1872-max-liebermann-women-plucking-geese', 'Women Plucking Geese', 'Max Liebermann', 1872, null, 'Realism', 'oil on canvas', 'Alte Nationalgalerie, Berlin', 3, 'object', 'https://nambatu.github.io/circart-preview/art/wbvtadtmax.jpg', 'Liebermann''s first large painting shows women plucking geese in a gloomy shed – a smelly, unglamorous job that was not considered a fit subject for art. Critics were unimpressed and branded him a painter of ugliness, but the railway tycoon Bethel Henry Strousberg bought it anyway. Liebermann later became the grand old man of German Impressionism.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('2bq5n4djc7', 'pack:german-artists:1875-adolph-menzel-the-iron-rolling-mill-modern-cyclopes', 'The Iron Rolling Mill (Modern Cyclopes)', 'Adolph Menzel', 1875, '1872–1875', 'Realism', 'oil on canvas', 'Alte Nationalgalerie, Berlin', 2, 'object', 'https://nambatu.github.io/circart-preview/art/2bq5n4djc7.jpg', 'One of the first great paintings of heavy industry: workers wrestle a glowing iron block in a Silesian mill that made railway tracks, with some 3,000 people on the payroll. On the right, men grab a quick meal while the shift carries on. The first buyer went bankrupt, and the National Gallery paid almost three times his price.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('subea8hgjw', 'pack:german-artists:1881-wilhelm-leibl-three-women-in-church', 'Three Women in Church', 'Wilhelm Leibl', 1881, 'c. 1878–1881 (some sources give 1882)', 'Realism', 'oil on panel', 'Hamburger Kunsthalle, Hamburg', 3, 'object', 'https://nambatu.github.io/circart-preview/art/subea8hgjw.jpg', 'Leibl painted this right inside a village church in Upper Bavaria, with local women as his models, and needed about three and a half years to finish it. When the parish priest died, his successor wanted the painter out – only the intervention of the Prince Regent of Bavaria let him finish.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('2zqk2h7su7', 'pack:german-artists:1901-gustav-klimt-judith-i', 'Judith I', 'Gustav Klimt', 1901, null, 'Art Nouveau', 'oil and gold leaf on canvas', 'Österreichische Galerie Belvedere, Vienna', 1, 'object', 'https://nambatu.github.io/circart-preview/art/2zqk2h7su7.jpg', 'Critics kept mistaking her for Salome, so Klimt had his brother make a metal frame engraved with ''Judith und Holofernes''. There''s no bloody sword – Holofernes'' head is simply cropped at the edge, and Judith''s half-closed eyes look more ecstatic than heroic. Her face is thought to be based on Adele Bloch-Bauer.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('6um67ca527', 'pack:german-artists:1903-k-the-kollwitz-woman-with-dead-child', 'Woman with Dead Child', 'Käthe Kollwitz', 1903, null, 'Expressionism', 'etching', 'Print – impressions in many collections', 2, 'object', 'https://nambatu.github.io/circart-preview/art/6um67ca527.jpg', 'A mother clutches her dead child with almost animal grief. Kollwitz drew on years as the wife of a doctor in a poor district of Berlin, where children died often, and used herself and her seven-year-old son Peter as models. Peter was later killed in the First World War, giving the image a terrible afterlife.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('wuffzfz4uf', 'pack:german-artists:1906-paula-modersohn-becker-self-portrait-on-her-sixth-wedding-day', 'Self-Portrait on Her Sixth Wedding Day', 'Paula Modersohn-Becker', 1906, null, 'Expressionism', 'oil tempera on cardboard', 'Paula Modersohn-Becker Museum, Bremen', 2, 'object', 'https://nambatu.github.io/circart-preview/art/wuffzfz4uf.jpg', 'Often called the first nude self-portrait by a woman painter. She looks pregnant but wasn''t – she had just left her husband to work in Paris, and painted this on their wedding anniversary (the title says sixth, though it was really the fifth). She died the following year, only weeks after giving birth to her daughter, aged 31.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('br9rh8ghu3', 'pack:german-artists:1911-franz-marc-yellow-cow', 'Yellow Cow', 'Franz Marc', 1911, null, 'Expressionism', 'oil on canvas', 'Solomon R. Guggenheim Museum, New York', 2, 'object', 'https://nambatu.github.io/circart-preview/art/br9rh8ghu3.jpg', 'Marc gave colours their own meanings: blue for the spiritual and masculine, yellow for the feminine and joyful, red for heavy, earthly matter. The happily leaping cow has been read as a veiled portrait of his wife Maria Franck, whom he married that same year. Marc was killed at Verdun in the First World War.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('ghfn3bemrk', 'pack:german-artists:1912-egon-schiele-portrait-of-wally', 'Portrait of Wally', 'Egon Schiele', 1912, null, 'Expressionism', 'oil on panel', 'Leopold Museum, Vienna', 2, 'object', 'https://nambatu.github.io/circart-preview/art/ghfn3bemrk.jpg', 'Wally Neuzil was Schiele''s lover and favourite model for several years. After the Nazi annexation of Austria, the painting was taken from its Jewish owner, the art dealer Lea Bondi Jaray. Decades later it was seized in New York while on loan, and the Leopold Museum finally settled with her heirs for 19 million dollars.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('8zgcpknqat', 'pack:german-artists:1913-august-macke-lady-in-a-green-jacket', 'Lady in a Green Jacket', 'August Macke', 1913, null, 'Expressionism', 'oil on canvas', 'Museum Ludwig, Cologne', 2, 'object', 'https://nambatu.github.io/circart-preview/art/8zgcpknqat.jpg', 'One of the first pictures Macke painted after moving to Lake Thun in Switzerland: elegant strollers, glowing colours and simplified, almost Cubist trees and houses, inspired by Robert Delaunay. Macke was killed in the first weeks of the First World War, aged just 27.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('bbtuyusxe3', 'pack:german-artists:1915-ernst-ludwig-kirchner-self-portrait-as-a-soldier', 'Self-Portrait as a Soldier', 'Ernst Ludwig Kirchner', 1915, null, 'Expressionism', 'oil on canvas', 'Allen Memorial Art Museum, Oberlin, Ohio', 2, 'object', 'https://nambatu.github.io/circart-preview/art/bbtuyusxe3.jpg', 'Kirchner shows himself in uniform with a bloody stump where his painting hand should be – yet he was never wounded. It''s an image of his terror of losing the ability to paint after he broke down during military service. The Nazis later confiscated it as ''degenerate art'' and mockingly retitled it ''Soldier with Whore''.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('5n9w7786dx', 'pack:german-artists:1919-max-beckmann-the-night', 'The Night', 'Max Beckmann', 1919, '1918–1919', 'Expressionism', 'oil on canvas', 'Kunstsammlung Nordrhein-Westfalen, Düsseldorf', 3, 'object', 'https://nambatu.github.io/circart-preview/art/5n9w7786dx.jpg', 'Intruders torture a family in a cramped attic – a nightmare vision of the violence in post-war Germany. Beckmann used himself as the model for the man being hanged and based the woman and child on his own wife and son. He had gone to war believing it would cleanse society and came back deeply disillusioned.', 'german-artists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('9vvsxkeu7e', 'pack:impressionists:1867-fr-d-ric-bazille-the-family-reunion', 'The Family Reunion', 'Frédéric Bazille', 1867, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, 'object', 'https://nambatu.github.io/circart-preview/art/9vvsxkeu7e.jpg', 'Bazille painted his relatives on the terrace of the family estate near Montpellier. He slipped himself in at the far left edge, as if he had just stepped into the photo. Three years later he was killed in the Franco-Prussian War, aged only 28.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('kneumagezr', 'pack:impressionists:1868-douard-manet-the-balcony', 'The Balcony', 'Édouard Manet', 1868, '1868–1869', 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/kneumagezr.jpg', 'The seated woman is the painter Berthe Morisot, in the first of many portraits Manet made of her. Critics at the 1869 Salon found the picture strange and stiff. René Magritte later painted his own version and swapped all the people for coffins.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('kvgx5wg76w', 'pack:impressionists:1870-edgar-degas-the-orchestra-at-the-opera', 'The Orchestra at the Opera', 'Edgar Degas', 1870, 'c. 1870', 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, 'object', 'https://nambatu.github.io/circart-preview/art/kvgx5wg76w.jpg', 'The bassoonist in the middle is Désiré Dihau, a friend of Degas who played in the Paris Opera orchestra. The painting began as his portrait. The dancers on stage are cut off at the neck, so the musicians steal the show for once.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('tk34mfb7dj', 'pack:impressionists:1872-berthe-morisot-the-cradle', 'The Cradle', 'Berthe Morisot', 1872, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/tk34mfb7dj.jpg', 'The young mother is Morisot''s sister Edma, watching over her baby daughter Blanche. Morisot showed it at the first Impressionist exhibition in 1874. She was the only woman in that first show.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('n2nk72ht6h', 'pack:impressionists:1873-claude-monet-poppy-field', 'Poppy Field', 'Claude Monet', 1873, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 1, 'object', 'https://nambatu.github.io/circart-preview/art/n2nk72ht6h.jpg', 'Look twice and you will find the same pair two times: Monet''s wife Camille and their son Jean walk down the hill at the top and again at the bottom. The red poppies are just quick dabs of paint. The picture was shown at the first Impressionist exhibition in 1874.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('spenasbppc', 'pack:impressionists:1873-armand-guillaumin-sunset-at-ivry', 'Sunset at Ivry', 'Armand Guillaumin', 1873, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, 'object', 'https://nambatu.github.io/circart-preview/art/spenasbppc.jpg', 'Guillaumin painted the smoking factory chimneys on the Seine outside Paris, a modern view his friends rarely chose. For years he worked a government railway job and painted in his spare time. In 1891 he won 100,000 francs in the state lottery and could finally paint full time.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4wzukn6p4j', 'pack:impressionists:1874-eva-gonzal-s-a-box-at-the-th-tre-des-italiens', 'A Box at the Théâtre des Italiens', 'Eva Gonzalès', 1874, 'c. 1874', 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, 'object', 'https://nambatu.github.io/circart-preview/art/4wzukn6p4j.jpg', 'Gonzalès was the only formal pupil of Édouard Manet. Her sister Jeanne and her future husband posed for this theatre scene. The Salon turned it down in 1874 but accepted it five years later.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('mwf72wrjju', 'pack:impressionists:1875-gustave-caillebotte-the-floor-scrapers', 'The Floor Scrapers', 'Gustave Caillebotte', 1875, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/mwf72wrjju.jpg', 'The Salon jury rejected it as vulgar, because workers scraping a floor did not count as a fit subject for art. Caillebotte then showed it at the second Impressionist exhibition in 1876. He was rich, so he also bought many of his friends'' paintings and left them to the French state.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('kekmxvsqbx', 'pack:impressionists:1875-claude-monet-woman-with-a-parasol-madame-monet-and-he', 'Woman with a Parasol – Madame Monet and Her Son', 'Claude Monet', 1875, null, 'Impressionism', 'oil on canvas', 'National Gallery of Art, Washington, D.C.', 1, 'object', 'https://nambatu.github.io/circart-preview/art/kekmxvsqbx.jpg', 'Monet painted his wife Camille and their son Jean on a windy summer day near Argenteuil. He worked outdoors and fast, probably in a single session of a few hours. You can almost feel the breeze in her veil.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('677cwgque4', 'pack:impressionists:1876-edgar-degas-the-ballet-class', 'The Ballet Class', 'Edgar Degas', 1876, '1873–1876', 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 1, 'object', 'https://nambatu.github.io/circart-preview/art/677cwgque4.jpg', 'The old man with the stick is Jules Perrot, once a star dancer and choreographer. Degas made dancers his big theme, and more than half of his works show them. He liked rehearsals better than shows, with all the stretching and waiting.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('647wtjgje8', 'pack:impressionists:1876-alfred-sisley-boat-in-the-flood-at-port-marly', 'Boat in the Flood at Port-Marly', 'Alfred Sisley', 1876, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, 'object', 'https://nambatu.github.io/circart-preview/art/647wtjgje8.jpg', 'When the Seine flooded the village of Port-Marly in 1876, Sisley set up his easel and painted the water in the streets. It is one of a series of flood pictures he made there. Sisley was British, though he was born and lived in France.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('wz89wq6adr', 'pack:impressionists:1877-claude-monet-the-saint-lazare-station', 'The Saint-Lazare Station', 'Claude Monet', 1877, null, 'Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/wz89wq6adr.jpg', 'Monet got permission to paint inside the busy Paris station and made about a dozen views of it. The story goes that trains were held back and stoked so he could catch the steam. Here the subject is really the smoke and light, with the trains as supporting actors.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4dn9n8jkdv', 'pack:impressionists:1878-mary-cassatt-little-girl-in-a-blue-armchair', 'Little Girl in a Blue Armchair', 'Mary Cassatt', 1878, null, 'Impressionism', 'oil on canvas', 'National Gallery of Art, Washington, D.C.', 2, 'object', 'https://nambatu.github.io/circart-preview/art/4dn9n8jkdv.jpg', 'Cassatt was the only American who exhibited with the Impressionists in Paris. Degas liked this picture so much that he helped her with part of the background. The bored little girl sprawled across the chair looks very modern for 1878.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('twqdfj89xa', 'pack:impressionists:1880-marie-bracquemond-on-the-terrace-at-s-vres', 'On the Terrace at Sèvres', 'Marie Bracquemond', 1880, null, 'Impressionism', 'oil on canvas', 'Artizon Museum, Tokyo (smaller version)', 3, 'object', 'https://nambatu.github.io/circart-preview/art/twqdfj89xa.jpg', 'The scene shows the terrace of the house in Sèvres that Bracquemond shared with her husband, the printmaker Félix Bracquemond. Her sister Louise is said to have posed for both women. There are two versions, and this smaller one hangs in Tokyo.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('bwkfbce63s', 'pack:impressionists:1881-pierre-auguste-renoir-two-sisters-on-the-terrace', 'Two Sisters (On the Terrace)', 'Pierre-Auguste Renoir', 1881, null, 'Impressionism', 'oil on canvas', 'Art Institute of Chicago', 2, 'object', 'https://nambatu.github.io/circart-preview/art/bwkfbce63s.jpg', 'Renoir painted it on the terrace of the Maison Fournaise in Chatou, the same riverside restaurant as his Luncheon of the Boating Party. Despite the title, the two girls were not sisters. The older one was a young actress, Jeanne Darlot.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('aeqpw9nuwk', 'pack:impressionists:1885-childe-hassam-rainy-day-columbus-avenue-boston', 'Rainy Day, Columbus Avenue, Boston', 'Childe Hassam', 1885, null, 'Impressionism', 'oil on canvas', 'Toledo Museum of Art, Toledo, Ohio', 3, 'object', 'https://nambatu.github.io/circart-preview/art/aeqpw9nuwk.jpg', 'Hassam loved wet streets, and here the pavement shines like a mirror under grey skies. He painted it in Boston just before he went to study in Paris. He later became one of the best-known American Impressionists.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('7akvwhtkbe', 'pack:impressionists:1887-paul-c-zanne-mont-sainte-victoire-with-large-pine', 'Mont Sainte-Victoire with Large Pine', 'Paul Cézanne', 1887, 'c. 1887', 'Post-Impressionism', 'oil on canvas', 'Courtauld Gallery, London', 2, 'object', 'https://nambatu.github.io/circart-preview/art/7akvwhtkbe.jpg', 'The mountain near his home town of Aix-en-Provence was Cézanne''s favourite model. He painted it again and again, in dozens of oils and watercolours. A mountain never fidgets, which helps when you work as slowly as he did.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('kpymwnjr7m', 'pack:impressionists:1888-paul-gauguin-vision-after-the-sermon', 'Vision After the Sermon', 'Paul Gauguin', 1888, null, 'Post-Impressionism', 'oil on canvas', 'Scottish National Gallery, Edinburgh', 2, 'object', 'https://nambatu.github.io/circart-preview/art/kpymwnjr7m.jpg', 'Breton women in white bonnets see the Bible story they have just heard: Jacob wrestling with an angel. Gauguin painted the ground flat red, which was a bold break with realism. He offered the painting to a local church, but the priest said no.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('usmamnaf49', 'pack:impressionists:1890-vincent-van-gogh-almond-blossoms', 'Almond Blossoms', 'Vincent van Gogh', 1890, null, 'Post-Impressionism', 'oil on canvas', 'Van Gogh Museum, Amsterdam', 1, 'object', 'https://nambatu.github.io/circart-preview/art/usmamnaf49.jpg', 'Van Gogh painted the blossoms as a gift when his brother Theo''s son was born. The baby was named Vincent after him. That nephew later helped found the Van Gogh Museum, where the painting hangs today.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('cprzv9t88h', 'pack:impressionists:1892-henri-de-toulouse-lautrec-at-the-moulin-rouge', 'At the Moulin Rouge', 'Henri de Toulouse-Lautrec', 1892, '1892–1895', 'Post-Impressionism', 'oil on canvas', 'Art Institute of Chicago', 2, 'object', 'https://nambatu.github.io/circart-preview/art/cprzv9t88h.jpg', 'Toulouse-Lautrec put himself in the picture: he is the short man in the background walking next to his tall cousin. The woman at the right edge has a ghostly green face from the stage lights. At some point that strip was cut off the canvas and later put back.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4qs36xpr43', 'pack:impressionists:1893-paul-c-zanne-the-basket-of-apples', 'The Basket of Apples', 'Paul Cézanne', 1893, 'c. 1893', 'Post-Impressionism', 'oil on canvas', 'Art Institute of Chicago', 2, 'object', 'https://nambatu.github.io/circart-preview/art/4qs36xpr43.jpg', 'Nothing in this still life quite lines up. The table edge breaks under the cloth, and the bottle leans as if it had a drink too many. Cézanne did this on purpose, showing objects from more than one angle, which later inspired the Cubists.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('zfh59s4uz2', 'pack:impressionists:1895-paul-signac-the-red-buoy', 'The Red Buoy', 'Paul Signac', 1895, null, 'Neo-Impressionism', 'oil on canvas', 'Musée d''Orsay, Paris', 3, 'object', 'https://nambatu.github.io/circart-preview/art/zfh59s4uz2.jpg', 'Signac built the whole harbour of Saint-Tropez out of small square dots of pure colour. He was a keen sailor and owned dozens of boats over his life. He moved to the then quiet fishing village in 1892 and helped make it famous among artists.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('h9ft63cbpy', 'pack:impressionists:1897-camille-pissarro-boulevard-montmartre-at-night', 'Boulevard Montmartre at Night', 'Camille Pissarro', 1897, null, 'Impressionism', 'oil on canvas', 'National Gallery, London', 2, 'object', 'https://nambatu.github.io/circart-preview/art/h9ft63cbpy.jpg', 'Pissarro painted a whole series of this Paris boulevard from his hotel window. An eye problem made it hard for him to work outdoors, so he painted from rooms with a good view. This is the only night scene in the series, with gas lamps glowing in the wet street.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('sn33faaxjv', 'pack:impressionists:1899-claude-monet-bridge-over-a-pond-of-water-lilies', 'Bridge over a Pond of Water Lilies', 'Claude Monet', 1899, null, 'Impressionism', 'oil on canvas', 'Metropolitan Museum of Art, New York', 1, 'object', 'https://nambatu.github.io/circart-preview/art/sn33faaxjv.jpg', 'Monet built this Japanese-style footbridge in his garden at Giverny. He even had a stream diverted to create the lily pond. He then painted the pond for the rest of his life. Talk about getting your money''s worth from a garden.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('tbpzd48u2t', 'pack:impressionists:1903-th-o-van-rysselberghe-the-reading', 'The Reading', 'Théo van Rysselberghe', 1903, null, 'Neo-Impressionism', 'oil on canvas', 'Museum of Fine Arts, Ghent', 3, 'object', 'https://nambatu.github.io/circart-preview/art/tbpzd48u2t.jpg', 'The Belgian poet Émile Verhaeren, in red, reads aloud to a group of friends. Among the listeners are the writers André Gide and Maurice Maeterlinck. Van Rysselberghe was a Belgian painter who worked in the dotted style of Seurat and Signac.', 'impressionists', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('aqeqszffzk', 'pack:renaissance:1423-gentile-da-fabriano-adoration-of-the-magi', 'Adoration of the Magi', 'Gentile da Fabriano', 1423, null, 'International Gothic', 'tempera on panel', 'Uffizi Gallery, Florence', 3, 'object', 'https://nambatu.github.io/circart-preview/art/aqeqszffzk.jpg', 'Palla Strozzi, the richest man in Florence at the time, ordered this altarpiece for his family chapel. Gentile used real gold and raised patterns so the kings'' clothes actually sparkle. The procession winds back through the hills like a medieval road trip.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('6shxgss2p3', 'pack:renaissance:1428-robert-campin-m-rode-altarpiece', 'Mérode Altarpiece', 'Robert Campin', 1428, 'c. 1427–1432', 'Northern Renaissance', 'oil on oak panel', 'The Cloisters, Metropolitan Museum of Art, New York', 3, 'object', 'https://nambatu.github.io/circart-preview/art/6shxgss2p3.jpg', 'The Annunciation happens in an ordinary Flemish living room. On the right wing, Joseph works as a carpenter and makes mousetraps. Some scholars read the trap as a symbol of Christ catching the devil.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('qsf3rve36g', 'pack:renaissance:1435-jan-van-eyck-madonna-of-chancellor-rolin', 'Madonna of Chancellor Rolin', 'Jan van Eyck', 1435, 'c. 1435', 'Northern Renaissance', 'oil on panel', 'Louvre, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/qsf3rve36g.jpg', 'Nicolas Rolin, the powerful chancellor of Burgundy, kneels face to face with the Virgin. Behind them a whole city stretches along a river, painted in tiny detail. Two little figures on the battlements peek out at the view, much like you do.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('3mnmxwzq85', 'pack:renaissance:1459-benozzo-gozzoli-procession-of-the-magi', 'Procession of the Magi', 'Benozzo Gozzoli', 1459, '1459–1461', 'Early Renaissance', 'fresco', 'Magi Chapel, Palazzo Medici Riccardi, Florence', 2, 'object', 'https://nambatu.github.io/circart-preview/art/3mnmxwzq85.jpg', 'This fresco covers the walls of the private chapel of the Medici family. The Medici rode along in the procession, painted as members of the royal party. Gozzoli added himself in the crowd and wrote his name on his red cap.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('8g4hs37hxg', 'pack:renaissance:1460-rogier-van-der-weyden-portrait-of-a-lady', 'Portrait of a Lady', 'Rogier van der Weyden', 1460, 'c. 1460', 'Northern Renaissance', 'oil on panel', 'National Gallery of Art, Washington, D.C.', 2, 'object', 'https://nambatu.github.io/circart-preview/art/8g4hs37hxg.jpg', 'Nobody knows who this young woman was. Rogier painted her see-through veil so finely that you can see the pins holding it. Her lowered eyes and folded hands make her look calm and a little shy.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('sgkvcp3jgk', 'pack:renaissance:1465-filippo-lippi-madonna-and-child-with-two-angels', 'Madonna and Child with Two Angels', 'Filippo Lippi', 1465, 'c. 1460–1465', 'Early Renaissance', 'tempera on panel', 'Uffizi Gallery, Florence', 3, 'object', 'https://nambatu.github.io/circart-preview/art/sgkvcp3jgk.jpg', 'Lippi was a monk who ran off with a young nun, Lucrezia Buti, and she is said to be the model for this Madonna. Their son Filippino Lippi also became a famous painter. Botticelli also learned his trade in Lippi''s workshop.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4y2udjrk2j', 'pack:renaissance:1470-petrus-christus-portrait-of-a-young-girl', 'Portrait of a Young Girl', 'Petrus Christus', 1470, 'c. 1470', 'Northern Renaissance', 'oil on oak panel', 'Gemäldegalerie, Berlin', 3, 'object', 'https://nambatu.github.io/circart-preview/art/4y2udjrk2j.jpg', 'This small panel is one of the first portraits to place the sitter in a real room instead of a flat dark background. It is tiny, less than 30 centimetres tall. The girl''s name remains a mystery.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('azb5em2j4n', 'pack:renaissance:1475-antonello-da-messina-saint-jerome-in-his-study', 'Saint Jerome in His Study', 'Antonello da Messina', 1475, 'c. 1475', 'Early Renaissance', 'oil on lime panel', 'National Gallery, London', 3, 'object', 'https://nambatu.github.io/circart-preview/art/azb5em2j4n.jpg', 'The saint reads in a wooden study built inside a huge stone hall. His lion lurks in the shadows on the right, so keep an eye out. The panel is so Flemish in style that it was once thought to be by Jan van Eyck.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('vjfb3sybzq', 'pack:renaissance:1475-sandro-botticelli-adoration-of-the-magi', 'Adoration of the Magi', 'Sandro Botticelli', 1475, 'c. 1475', 'Early Renaissance', 'tempera on panel', 'Uffizi Gallery, Florence', 2, 'object', 'https://nambatu.github.io/circart-preview/art/vjfb3sybzq.jpg', 'Several members of the Medici family appear as the kings and their followers. The man in the yellow cloak at the far right, looking straight at you, is thought to be Botticelli himself. It is one of his earliest major works.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('8f8zv5uzph', 'pack:renaissance:1476-hugo-van-der-goes-portinari-altarpiece', 'Portinari Altarpiece', 'Hugo van der Goes', 1476, 'c. 1475–1476', 'Northern Renaissance', 'oil on panel', 'Uffizi Gallery, Florence', 3, 'object', 'https://nambatu.github.io/circart-preview/art/8f8zv5uzph.jpg', 'Tommaso Portinari, the Medici bank''s agent in Bruges, ordered this huge altarpiece and shipped it to Florence. Its rough, realistic shepherds amazed the Italian painters. The Portinari family kneels in the side panels with their patron saints.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('a6a36cj4c5', 'pack:renaissance:1487-hans-memling-diptych-of-maarten-van-nieuwenhove', 'Diptych of Maarten van Nieuwenhove', 'Hans Memling', 1487, null, 'Northern Renaissance', 'oil on oak panel', 'Old St. John''s Hospital, Bruges', 3, 'object', 'https://nambatu.github.io/circart-preview/art/a6a36cj4c5.jpg', 'The young man on the right was 23 years old, as the frame tells us. He prays to the Madonna on the left panel, who offers the child an apple. A round mirror behind her reflects both of them in the same room.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('8x55g8w39w', 'pack:renaissance:1490-leonardo-da-vinci-lady-with-an-ermine', 'Lady with an Ermine', 'Leonardo da Vinci', 1490, 'c. 1489–1491', 'High Renaissance', 'oil on walnut panel', 'Czartoryski Museum, Kraków', 1, 'object', 'https://nambatu.github.io/circart-preview/art/8x55g8w39w.jpg', 'The sitter is Cecilia Gallerani, a young woman at the court of the Duke of Milan. The ermine is a pun, because the Greek word for the animal sounds like her surname. The Nazis stole the painting during the Second World War, and it came back to Kraków in 1946.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('747v2s7qsz', 'pack:renaissance:1500-hieronymus-bosch-the-ship-of-fools', 'The Ship of Fools', 'Hieronymus Bosch', 1500, 'c. 1490–1500', 'Northern Renaissance', 'oil on panel', 'Louvre, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/747v2s7qsz.jpg', 'A monk and a nun sing and snack in a boat that is going nowhere. Bosch mocks greed and silliness, and a tree serves as the mast. The panel is a fragment, cut from a larger work long ago.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('daeumtv88q', 'pack:renaissance:1501-giovanni-bellini-portrait-of-doge-leonardo-loredan', 'Portrait of Doge Leonardo Loredan', 'Giovanni Bellini', 1501, '1501–1502', 'Venetian Renaissance', 'oil on poplar panel', 'National Gallery, London', 2, 'object', 'https://nambatu.github.io/circart-preview/art/daeumtv88q.jpg', 'Loredan had just become Doge, the ruler of Venice, and he stayed in office for twenty years. Bellini painted his damask robe and its bell-shaped buttons in loving detail. He signed on a little paper slip stuck to the stone ledge.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('psc73phfh3', 'pack:renaissance:1512-raphael-sistine-madonna', 'Sistine Madonna', 'Raphael', 1512, 'c. 1512–1513', 'High Renaissance', 'oil on canvas', 'Gemäldegalerie Alte Meister, Dresden', 1, 'object', 'https://nambatu.github.io/circart-preview/art/psc73phfh3.jpg', 'Pope Julius II ordered it for the church of San Sisto in Piacenza. The two bored little angels at the bottom became world famous on their own, from stamps to tea towels. After the Second World War the Soviets took it to Moscow and gave it back to Dresden in 1955.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('54vjhtdhxn', 'pack:renaissance:1514-quentin-matsys-the-moneylender-and-his-wife', 'The Moneylender and His Wife', 'Quentin Matsys', 1514, null, 'Northern Renaissance', 'oil on panel', 'Louvre, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/54vjhtdhxn.jpg', 'The man weighs coins while his wife is distracted from her prayer book. A small round mirror on the table reflects a man by a window, a nod to Jan van Eyck. It is an early look at money and morals, and the scales are tipped in favour of gold.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('ythvznam6x', 'pack:renaissance:1518-titian-assumption-of-the-virgin', 'Assumption of the Virgin', 'Titian', 1518, '1516–1518', 'Venetian Renaissance', 'oil on panel', 'Santa Maria Gloriosa dei Frari, Venice', 2, 'object', 'https://nambatu.github.io/circart-preview/art/ythvznam6x.jpg', 'At almost seven metres tall, it is the biggest altarpiece in Venice. Its unveiling in 1518 made Titian the leading painter in Venice. Mary rises to heaven in a red dress while the apostles below reach up in amazement.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('qr9en7qc6h', 'pack:renaissance:1528-pontormo-deposition-from-the-cross', 'Deposition from the Cross', 'Pontormo', 1528, '1525–1528', 'Mannerism', 'oil on panel', 'Santa Felicita, Florence', 2, 'object', 'https://nambatu.github.io/circart-preview/art/qr9en7qc6h.jpg', 'There is no cross in this Deposition, and no ground to stand on either. The figures seem to float in candy pink and sky blue. The bearded man at the far right is thought to be Pontormo himself.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('cz4877g66d', 'pack:renaissance:1535-parmigianino-madonna-with-the-long-neck', 'Madonna with the Long Neck', 'Parmigianino', 1535, '1534–1540', 'Mannerism', 'oil on panel', 'Uffizi Gallery, Florence', 2, 'object', 'https://nambatu.github.io/circart-preview/art/cz4877g66d.jpg', 'Parmigianino stretched the Madonna on purpose, from her swan-like neck to her long fingers. He never finished it before he died in 1540. That is why only one column stands in the background where a whole row was planned.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('yw6htvrgpx', 'pack:renaissance:1545-bronzino-eleanor-of-toledo-with-her-son-giovanni', 'Eleanor of Toledo with Her Son Giovanni', 'Bronzino', 1545, 'c. 1545', 'Mannerism', 'oil on panel', 'Uffizi Gallery, Florence', 2, 'object', 'https://nambatu.github.io/circart-preview/art/yw6htvrgpx.jpg', 'Eleanor was the Spanish-born wife of Cosimo I de'' Medici, Duke of Florence. Her brocade dress is so detailed that you can almost feel its weight. A few years later she bought the Palazzo Pitti, which became the Medici home.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('4uwrrhee7q', 'pack:renaissance:1555-sofonisba-anguissola-the-chess-game', 'The Chess Game', 'Sofonisba Anguissola', 1555, null, 'Mannerism', 'oil on canvas', 'National Museum, Poznań', 3, 'object', 'https://nambatu.github.io/circart-preview/art/4uwrrhee7q.jpg', 'Three of the painter''s sisters play chess while a maid looks on. The oldest looks out at us calmly, as if she already knows who will win. Anguissola later became a court painter to King Philip II of Spain.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('svvt8f3avs', 'pack:renaissance:1563-paolo-veronese-the-wedding-at-cana', 'The Wedding at Cana', 'Paolo Veronese', 1563, '1562–1563', 'Venetian Renaissance', 'oil on canvas', 'Louvre, Paris', 2, 'object', 'https://nambatu.github.io/circart-preview/art/svvt8f3avs.jpg', 'At almost ten metres wide, it is the largest painting in the Louvre. It hangs in the same room as the Mona Lisa, facing her. Napoleon''s troops carried it off from a Venetian monastery in 1797, and it never went back.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('eefpr847tr', 'pack:renaissance:1563-giuseppe-arcimboldo-summer', 'Summer', 'Giuseppe Arcimboldo', 1563, null, 'Mannerism', 'oil on limewood panel', 'Kunsthistorisches Museum, Vienna', 2, 'object', 'https://nambatu.github.io/circart-preview/art/eefpr847tr.jpg', 'This face is made entirely of fruit and vegetables, with a pea pod for teeth. It belongs to Arcimboldo''s Four Seasons, made for the Habsburg emperor. He wove his name into the straw collar and put the year on the shoulder, hidden in plain sight.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('uyd7v73fc2', 'pack:renaissance:1567-pieter-bruegel-the-elder-the-peasant-wedding', 'The Peasant Wedding', 'Pieter Bruegel the Elder', 1567, 'c. 1567', 'Northern Renaissance', 'oil on panel', 'Kunsthistorisches Museum, Vienna', 1, 'object', 'https://nambatu.github.io/circart-preview/art/uyd7v73fc2.jpg', 'The bride sits under a paper crown in front of a green cloth. Nobody is quite sure which guest is the groom. Two men carry bowls of porridge on an old door used as a tray, a very Bruegel kind of catering.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
insert into public.cards (id, source_id, title, artist, year, date_note, movement, medium, location, tier, visual_type, image_url, trivia, pack_id, active) values ('dvf7n5kae3', 'pack:renaissance:1579-el-greco-the-disrobing-of-christ', 'The Disrobing of Christ', 'El Greco', 1579, '1577–1579', 'Mannerism', 'oil on canvas', 'Sacristy of Toledo Cathedral, Toledo', 3, 'object', 'https://nambatu.github.io/circart-preview/art/dvf7n5kae3.jpg', 'This was El Greco''s first big commission in Toledo, where he spent the rest of his life. The cathedral clergy complained about details like the crowd placed above Christ''s head. The dispute over the price ended up in court.', 'renaissance', false) on conflict (id) do update set title = excluded.title, artist = excluded.artist, year = excluded.year, date_note = excluded.date_note, movement = excluded.movement, medium = excluded.medium, location = excluded.location, tier = excluded.tier, image_url = excluded.image_url, trivia = excluded.trivia, pack_id = excluded.pack_id, active = false, updated_at = now();
